     1→// ============================================================
     2→// minicc.fl - Mini Compiler for FreeLang (FreeLang Version)
     3→// Self-Hosting Proof: Compiles a subset of FreeLang to C
     4→// ============================================================
     5→
     6→// ============================================================
     7→// Part 1: TOKEN CONSTANTS
     8→// ============================================================
     9→
    10→let TOK_EOF: i64 = 0;
    11→let TOK_INT: i64 = 1;
    12→let TOK_IDENT: i64 = 2;
    13→let TOK_PLUS: i64 = 3;
    14→let TOK_MINUS: i64 = 4;
    15→let TOK_STAR: i64 = 5;
    16→let TOK_SLASH: i64 = 6;
    17→let TOK_EQ: i64 = 7;
    18→let TOK_NE: i64 = 8;
    19→let TOK_LT: i64 = 9;
    20→let TOK_GT: i64 = 10;
    21→let TOK_LE: i64 = 11;
    22→let TOK_GE: i64 = 12;
    23→let TOK_ASSIGN: i64 = 13;
    24→let TOK_LPAREN: i64 = 14;
    25→let TOK_RPAREN: i64 = 15;
    26→let TOK_LBRACE: i64 = 16;
    27→let TOK_RBRACE: i64 = 17;
    28→let TOK_SEMICOLON: i64 = 18;
    29→let TOK_COMMA: i64 = 19;
    30→let TOK_COLON: i64 = 20;
    31→let TOK_AND: i64 = 21;
    32→let TOK_OR: i64 = 22;
    33→let TOK_NOT: i64 = 23;
    34→let TOK_FN: i64 = 24;
    35→let TOK_LET: i64 = 25;
    36→let TOK_VAR: i64 = 26;
    37→let TOK_RETURN: i64 = 27;
    38→let TOK_IF: i64 = 28;
    39→let TOK_ELSE: i64 = 29;
    40→let TOK_WHILE: i64 = 30;
    41→let TOK_FOR: i64 = 31;
    42→let TOK_MATCH: i64 = 32;
    43→let TOK_ARROW: i64 = 33;
    44→let TOK_STRING: i64 = 34;
    45→
    46→// ============================================================
    47→// Part 2: DATA STRUCTURES
    48→// ============================================================
    49→
    50→struct Token {
    51→    type: i64,
    52→    value: i64,
    53→    name: string,
    54→    str_val: string,
    55→}
    56→
    57→struct Lexer {
    58→    input: string,
    59→    pos: i64,
    60→    length: i64,
    61→    tokens: [Token],
    62→    tokens_count: i64,
    63→}
    64→
    65→// ============================================================
    66→// Part 3: AST CONSTANTS
    67→// ============================================================
    68→
    69→let AST_PROGRAM: i64 = 1;
    70→let AST_FUNC: i64 = 2;
    71→let AST_VAR: i64 = 3;
    72→let AST_BINOP: i64 = 4;
    73→let AST_LITERAL: i64 = 5;
    74→let AST_IDENT: i64 = 6;
    75→let AST_CALL: i64 = 7;
    76→let AST_IF: i64 = 8;
    77→let AST_WHILE: i64 = 9;
    78→let AST_RETURN: i64 = 10;
    79→let AST_EXPR_STMT: i64 = 11;
    80→let AST_ASSIGN: i64 = 12;
    81→let AST_STRING: i64 = 13;
    82→
    83→struct ASTNode {
    84→    type: i64,
    85→    name: string,
    86→    type_name: string,
    87→    value: i64,
    88→    op: i64,
    89→    then_count: i64,
    90→    str_val: string,
    91→    left: *ASTNode,
    92→    right: *ASTNode,
    93→}
    94→
    95→struct Parser {
    96→    tokens: [Token],
    97→    tokens_count: i64,
    98→    pos: i64,
    99→    nodes: [ASTNode],
   100→    nodes_count: i64,
   101→}
   102→
   103→// ============================================================
   104→// Part 4: HELPER FUNCTIONS
   105→// ============================================================
   106→
   107→fn is_digit(c: i64) -> i64 {
   108→    return c >= 48 && c <= 57;  // '0' = 48, '9' = 57
   109→}
   110→
   111→fn is_alpha(c: i64) -> i64 {
   112→    return (c >= 65 && c <= 90) || (c >= 97 && c <= 122);  // A-Z, a-z
   113→}
   114→
   115→fn is_alnum(c: i64) -> i64 {
   116→    return is_alpha(c) || is_digit(c);
   117→}
   118→
   119→fn is_space(c: i64) -> i64 {
   120→    return c == 32 || c == 9 || c == 10 || c == 13;  // space, tab, newline, CR
   121→}
   122→
   123→fn is_keyword(name: string) -> i64 {
   124→    if name == "fn" {
   125→        return TOK_FN;
   126→    }
   127→    if name == "let" {
   128→        return TOK_LET;
   129→    }
   130→    if name == "var" {
   131→        return TOK_VAR;
   132→    }
   133→    if name == "return" {
   134→        return TOK_RETURN;
   135→    }
   136→    if name == "if" {
   137→        return TOK_IF;
   138→    }
   139→    if name == "else" {
   140→        return TOK_ELSE;
   141→    }
   142→    if name == "while" {
   143→        return TOK_WHILE;
   144→    }
   145→    if name == "for" {
   146→        return TOK_FOR;
   147→    }
   148→    if name == "match" {
   149→        return TOK_MATCH;
   150→    }
   151→    return 0;
   152→}
   153→
   154→// ============================================================
   155→// Part 5: LEXER IMPLEMENTATION
   156→// ============================================================
   157→
   158→fn tokenize(input: string) -> Lexer {
   159→    var lex: Lexer;
   160→    lex.input = input;
   161→    lex.length = length(input);
   162→    lex.pos = 0;
   163→    lex.tokens_count = 0;
   164→
   165→    while lex.pos < lex.length {
   166→        var c: i64 = char_at(input, lex.pos);
   167→
   168→        if c == 0 {
   169→            break;
   170→        }
   171→
   172→        // Skip whitespace
   173→        if is_space(c) {
   174→            lex.pos = lex.pos + 1;
   175→            continue;
   176→        }
   177→
   178→        // Skip line comments
   179→        if c == 47 && lex.pos + 1 < lex.length && char_at(input, lex.pos + 1) == 47 {
   180→            while lex.pos < lex.length && char_at(input, lex.pos) != 10 {
   181→                lex.pos = lex.pos + 1;
   182→            }
   183→            continue;
   184→        }
   185→
   186→        var tok: Token;
   187→        tok.type = 0;
   188→        tok.value = 0;
   189→        tok.name = "";
   190→        tok.str_val = "";
   191→
   192→        // Parse integers
   193→        if is_digit(c) {
   194→            var val: i64 = 0;
   195→            while lex.pos < lex.length && is_digit(char_at(input, lex.pos)) {
   196→                var digit: i64 = char_at(input, lex.pos) - 48;
   197→                val = val * 10 + digit;
   198→                lex.pos = lex.pos + 1;
   199→            }
   200→            tok.type = TOK_INT;
   201→            tok.value = val;
   202→            lex.tokens[lex.tokens_count] = tok;
   203→            lex.tokens_count = lex.tokens_count + 1;
   204→            continue;
   205→        }
   206→
   207→        // Parse identifiers and keywords
   208→        if is_alpha(c) || c == 95 {  // '_' = 95
   209→            var name: string = "";
   210→            while lex.pos < lex.length && (is_alnum(char_at(input, lex.pos)) || char_at(input, lex.pos) == 95) {
   211→                name = name + substring(input, lex.pos, lex.pos + 1);
   212→                lex.pos = lex.pos + 1;
   213→            }
   214→            var kw: i64 = is_keyword(name);
   215→            tok.type = if kw != 0 { kw } else { TOK_IDENT };
   216→            tok.name = name;
   217→            lex.tokens[lex.tokens_count] = tok;
   218→            lex.tokens_count = lex.tokens_count + 1;
   219→            continue;
   220→        }
   221→
   222→        // Parse strings
   223→        if c == 34 {  // '"' = 34
   224→            lex.pos = lex.pos + 1;
   225→            var str_val: string = "";
   226→            while lex.pos < lex.length && char_at(input, lex.pos) != 34 {
   227→                var ch: i64 = char_at(input, lex.pos);
   228→                if ch == 92 && lex.pos + 1 < lex.length {  // '\\' = 92
   229→                    lex.pos = lex.pos + 1;
   230→                    var escaped: i64 = char_at(input, lex.pos);
   231→                    if escaped == 110 {  // 'n' = 110
   232→                        str_val = str_val + substring(input, 0, 0);  // newline
   233→                    } else if escaped == 116 {  // 't' = 116
   234→                        str_val = str_val + substring(input, 0, 0);  // tab
   235→                    } else {
   236→                        str_val = str_val + substring(input, lex.pos, lex.pos + 1);
   237→                    }
   238→                    lex.pos = lex.pos + 1;
   239→                } else {
   240→                    str_val = str_val + substring(input, lex.pos, lex.pos + 1);
   241→                    lex.pos = lex.pos + 1;
   242→                }
   243→            }
   244→            if lex.pos < lex.length {
   245→                lex.pos = lex.pos + 1;  // skip closing "
   246→            }
   247→            tok.type = TOK_STRING;
   248→            tok.str_val = str_val;
   249→            lex.tokens[lex.tokens_count] = tok;
   250→            lex.tokens_count = lex.tokens_count + 1;
   251→            continue;
   252→        }
   253→
   254→        // Parse operators and punctuation
   255→        var next_char: i64 = if lex.pos + 1 < lex.length { char_at(input, lex.pos + 1) } else { 0 };
   256→
   257→        if c == 45 && next_char == 62 {  // '->'
   258→            tok.type = TOK_ARROW;
   259→            lex.pos = lex.pos + 2;
   260→        } else if c == 61 && next_char == 61 {  // '=='
   261→            tok.type = TOK_EQ;
   262→            lex.pos = lex.pos + 2;
   263→        } else if c == 33 && next_char == 61 {  // '!='
   264→            tok.type = TOK_NE;
   265→            lex.pos = lex.pos + 2;
   266→        } else if c == 60 && next_char == 61 {  // '<='
   267→            tok.type = TOK_LE;
   268→            lex.pos = lex.pos + 2;
   269→        } else if c == 62 && next_char == 61 {  // '>='
   270→            tok.type = TOK_GE;
   271→            lex.pos = lex.pos + 2;
   272→        } else if c == 38 && next_char == 38 {  // '&&'
   273→            tok.type = TOK_AND;
   274→            lex.pos = lex.pos + 2;
   275→        } else if c == 124 && next_char == 124 {  // '||'
   276→            tok.type = TOK_OR;
   277→            lex.pos = lex.pos + 2;
   278→        } else if c == 43 {  // '+'
   279→            tok.type = TOK_PLUS;
   280→            lex.pos = lex.pos + 1;
   281→        } else if c == 45 {  // '-'
   282→            tok.type = TOK_MINUS;
   283→            lex.pos = lex.pos + 1;
   284→        } else if c == 42 {  // '*'
   285→            tok.type = TOK_STAR;
   286→            lex.pos = lex.pos + 1;
   287→        } else if c == 47 {  // '/'
   288→            tok.type = TOK_SLASH;
   289→            lex.pos = lex.pos + 1;
   290→        } else if c == 61 {  // '='
   291→            tok.type = TOK_ASSIGN;
   292→            lex.pos = lex.pos + 1;
   293→        } else if c == 33 {  // '!'
   294→            tok.type = TOK_NOT;
   295→            lex.pos = lex.pos + 1;
   296→        } else if c == 60 {  // '<'
   297→            tok.type = TOK_LT;
   298→            lex.pos = lex.pos + 1;
   299→        } else if c == 62 {  // '>'
   300→            tok.type = TOK_GT;
   301→            lex.pos = lex.pos + 1;
   302→        } else if c == 40 {  // '('
   303→            tok.type = TOK_LPAREN;
   304→            lex.pos = lex.pos + 1;
   305→        } else if c == 41 {  // ')'
   306→            tok.type = TOK_RPAREN;
   307→            lex.pos = lex.pos + 1;
   308→        } else if c == 123 {  // '{'
   309→            tok.type = TOK_LBRACE;
   310→            lex.pos = lex.pos + 1;
   311→        } else if c == 125 {  // '}'
   312→            tok.type = TOK_RBRACE;
   313→            lex.pos = lex.pos + 1;
   314→        } else if c == 59 {  // ';'
   315→            tok.type = TOK_SEMICOLON;
   316→            lex.pos = lex.pos + 1;
   317→        } else if c == 44 {  // ','
   318→            tok.type = TOK_COMMA;
   319→            lex.pos = lex.pos + 1;
   320→        } else if c == 58 {  // ':'
   321→            tok.type = TOK_COLON;
   322→            lex.pos = lex.pos + 1;
   323→        } else {
   324→            lex.pos = lex.pos + 1;
   325→            continue;
   326→        }
   327→
   328→        if tok.type != 0 {
   329→            lex.tokens[lex.tokens_count] = tok;
   330→            lex.tokens_count = lex.tokens_count + 1;
   331→        }
   332→    }
   333→
   334→    // Add EOF token
   335→    var eof: Token;
   336→    eof.type = TOK_EOF;
   337→    eof.value = 0;
   338→    eof.name = "";
   339→    eof.str_val = "";
   340→    lex.tokens[lex.tokens_count] = eof;
   341→    lex.tokens_count = lex.tokens_count + 1;
   342→
   343→    return lex;
   344→}
   345→
   346→// ============================================================
   347→// Part 6: PARSER HELPERS
   348→// ============================================================
   349→
   350→fn token_at(p: *Parser) -> *Token {
   351→    var idx: i64 = p.pos;
   352→    if idx >= p.tokens_count {
   353→        idx = p.tokens_count - 1;
   354→    }
   355→    return &p.tokens[idx];
   356→}
   357→
   358→fn advance(p: *Parser) {
   359→    if p.pos < p.tokens_count - 1 {
   360→        p.pos = p.pos + 1;
   361→    }
   362→}
   363→
   364→fn match_token(p: *Parser, tok_type: i64) -> i64 {
   365→    var cur: *Token = token_at(p);
   366→    return if cur.type == tok_type { 1 } else { 0 };
   367→}
   368→
   369→fn consume(p: *Parser, tok_type: i64) -> i64 {
   370→    if match_token(p, tok_type) == 1 {
   371→        advance(p);
   372→        return 1;
   373→    }
   374→    return 0;
   375→}
