   377→fn new_ast_node(typ: i64) -> ASTNode {
   378→    var n: ASTNode;
   379→    n.type = typ;
   380→    n.value = 0;
   381→    n.op = 0;
   382→    n.then_count = 0;
   383→    n.name = "";
   384→    n.type_name = "";
   385→    n.str_val = "";
   386→    n.left = 0;
   387→    n.right = 0;
