   401→fn parse_program(p: *Parser) -> ASTNode {
   402→    var prog: ASTNode = new_ast_node(AST_PROGRAM);
   403→
   404→    while match_token(p, TOK_FN) == 1 {
   405→        advance(p);
   406→        var fn_node: ASTNode = new_ast_node(AST_FUNC);
   407→
   408→        if match_token(p, TOK_IDENT) == 1 {
   409→            var cur: *Token = token_at(p);
   410→            fn_node.name = cur.name;
   411→            advance(p);
   412→        }
   413→
   414→        consume(p, TOK_LPAREN);
   415→
   416→        while match_token(p, TOK_RPAREN) == 0 && match_token(p, TOK_EOF) == 0 {
   417→            if match_token(p, TOK_IDENT) == 0 {
   418→                break;
   419→            }
   420→
   421→            var param_idx: i64 = fn_node.op;  // Reuse op field for param count
   422→            var cur: *Token = token_at(p);
   423→            // Store param name (simplified - real version needs proper storage)
   424→            advance(p);
   425→
   426→            consume(p, TOK_COLON);
   427→
   428→            if match_token(p, TOK_IDENT) == 1 {
   429→                var type_tok: *Token = token_at(p);
   430→                // Store param type (simplified)
   431→                advance(p);
   432→            }
   433→
   434→            fn_node.op = fn_node.op + 1;  // Increment param count
   435→            consume(p, TOK_COMMA);
   436→        }
   437→
   438→        consume(p, TOK_RPAREN);
   439→        consume(p, TOK_ARROW);
   440→
   441→        if match_token(p, TOK_IDENT) == 1 {
   442→            var ret_type: *Token = token_at(p);
   443→            fn_node.type_name = ret_type.name;
   444→            advance(p);
   445→        }
   446→
   447→        consume(p, TOK_LBRACE);
   448→
   449→        while match_token(p, TOK_RBRACE) == 0 && match_token(p, TOK_EOF) == 0 {
   450→            var stmt: ASTNode = parse_stmt(p);
   451→            // Store statement (simplified)
   452→            fn_node.then_count = fn_node.then_count + 1;
   453→        }
   454→
   455→        consume(p, TOK_RBRACE);
   456→
   457→        // Store function in program (simplified)
   458→    }
   459→
   460→    return prog;
   461→}
