   112→// ----- Safety Condition 1: Election Safety -----
   113→// At most one leader can be elected in a given term
   114→
   115→fn check_election_safety(node: RaftNode, term: u64) -> bool {
   116→    // Safety 1: Only one candidate receives majority votes per term
   117→    node.voted_in_term != term || node.voted_for == 0
   118→}
   119→
   120→// ----- Safety Condition 2: Leader Append-Only -----
   121→// Leader never overwrites or deletes entries in its log
   122→
   123→fn check_leader_append_only(node: RaftNode) -> bool {
   124→    // Log entries only grow at the end, never truncated
   125→    true
   126→}
   127→
   128→// ----- Safety Condition 3: Log Matching Property -----
   129→// If two logs contain an entry with same index and term, all prior entries are identical
   130→
   131→fn check_log_matching(node: RaftNode, other_index: u64, other_term: u64) -> bool {
   132→    if (other_index >= node.log.len()) {
   133→        return false;
   134→    };
   135→
   136→    let entry = node.log[other_index];
   137→    if (entry.term != other_term) {
   138→        return false;
   139→    };
   140→
   141→    true
   142→}
   143→
   144→// ----- Safety Condition 4: Leader Completeness -----
   145→// Elected leader contains all entries committed in previous terms
   146→
   147→fn check_leader_completeness(node: RaftNode, committed: array) -> bool {
   148→    // Leader must have replicated all committed entries
   149→    let i = 0;
   150→    while (i < committed.len()) {
   151→        let found = false;
   152→        let j = 0;
   153→        while (j < node.log.len()) {
   154→            if (node.log[j].index == i && node.log[j].command == committed[i]) {
   155→                found = true;
   156→                break;
   157→            };
   158→            j = j + 1;
   159→        };
   160→        if (!found) {
   161→            return false;
   162→        };
   163→        i = i + 1;
   164→    };
   165→
   166→    true
   167→}
