   169→// ----- Safety Condition 5: State Machine Safety -----
   170→// All nodes apply entries in the same order
   171→
   172→fn apply_to_state_machine(node: RaftNode, state: array) -> array {
   173→    let new_state = state;
   174→    while (node.last_applied < node.commit_index) {
   175→        node.last_applied = node.last_applied + 1;
   176→        let entry = node.log[node.last_applied];
   177→        new_state.push(entry.command);
   178→    };
   179→
   180→    new_state
   181→}
