   183→// ----- Key Method 1: start_election -----
   184→// Candidate increments term, requests votes from all peers
   185→
   186→fn start_election(node: RaftNode) -> RaftNode {
   187→    // Transition to Candidate
   188→    node.state = RaftState.Candidate;
   189→    node.current_term = node.current_term + 1;
   190→    node.votes_received = 1;  // Vote for self
   191→    node.voted_for = node.id;
   192→    node.voted_in_term = node.current_term;
   193→    node.election_elapsed_ms = 0;
   194→
   195→    // Log: "Candidate advances its term and requests votes"
   196→    print("Node " + node.id + " starts election for term " + node.current_term);
   197→
