   361→fn min(a: u64, b: u64) -> u64 {
   362→    if (a < b) a else b
   363→}
   364→
   365→// ----- Key Method 6: commit_entries -----
   366→// Leader commits entries that are replicated on majority
   367→
   368→fn commit_entries(node: RaftNode) -> RaftNode {
   369→    if (node.state != RaftState.Leader) {
   370→        return node;
   371→    };
   372→
   373→    // Find highest index replicated on majority
   374→    let mut sorted_indices = [];
   375→    let i = 0;
   376→    while (i < node.num_nodes) {
   377→        sorted_indices.push(node.match_index[i]);
   378→        i = i + 1;
   379→    };
   380→
   381→    // Sort indices (descending)
   382→    let j = 0;
   383→    while (j < sorted_indices.len()) {
   384→        let k = j + 1;
   385→        while (k < sorted_indices.len()) {
   386→            if (sorted_indices[k] > sorted_indices[j]) {
   387→                let temp = sorted_indices[j];
   388→                sorted_indices[j] = sorted_indices[k];
   389→                sorted_indices[k] = temp;
   390→            };
   391→            k = k + 1;
   392→        };
   393→        j = j + 1;
   394→    };
   395→
   396→    // Get majority index (floor of num_nodes / 2)
   397→    let majority_idx = node.num_nodes / 2;
   398→    let majority_match = sorted_indices[majority_idx];
   399→
   400→    // Update commit_index if entry is from current term
   401→    if (majority_match > node.commit_index && majority_match < node.log.len()) {
   402→        let entry = node.log[majority_match];
   403→        if (entry.term == node.current_term) {
   404→            node.commit_index = majority_match;
   405→            print("Node " + node.id + " commits entry at index " + majority_match);
   406→        };
   407→    };
   408→
   409→    node
   410→}
   411→
   412→// ----- Key Method 7: apply_committed -----
   413→// Apply committed entries to state machine
   414→
   415→fn apply_committed(node: RaftNode) -> RaftNode {
   416→    while (node.last_applied < node.commit_index) {
   417→        node.last_applied = node.last_applied + 1;
   418→        if (node.last_applied < node.log.len()) {
   419→            let entry = node.log[node.last_applied];
   420→            print("Node " + node.id + " applies: " + entry.command);
   421→        };
   422→    };
   423→
   424→    node
   425→}
   426→
   427→// ----- Key Method 8: reset_election_timeout -----
   428→// Reset election timer on heartbeat
   429→
   430→fn reset_election_timeout(node: RaftNode) -> RaftNode {
   431→    node.election_elapsed_ms = 0;
   432→    node
   433→}
