     6→// ----- Structures -----
     7→
     8→struct HashNode {
     9→    hash: u64,
    10→    node_id: u32,
    11→    is_virtual: bool,
    12→}
    13→
    14→struct ConsistentHashRing {
    15→    virtual_nodes: u32,
    16→    nodes: array,              // Sorted array of HashNode
    17→    node_list: array,          // Actual node IDs
    18→    hash_map: map,             // hash -> node_id
    19→}
    20→
    21→struct Shard {
    22→    id: u32,
    23→    key_range_start: string,
    24→    key_range_end: string,
    25→    primary_node: u32,
    26→    replica_nodes: array,
    27→    size_bytes: u64,
    28→    created_at: u64,
    29→}
    30→
    31→struct ShardedKVStore {
    32→    shards: array,
