   363→// ----- Hotspot Detection -----
   364→
   365→fn detect_hotspots(store: ShardedKVStore) -> array {
   366→    let stats = get_balance_stats(store);
   367→    let hotspots = [];
   368→
   369→    // Calculate average and std dev
   370→    let total = 0;
   371→    let i = 0;
   372→    while (i < stats.len()) {
   373→        total = total + stats[i].key_count;
   374→        i = i + 1;
   375→    };
   376→
   377→    let avg = total / stats.len();
   378→    let sum_sq_diff = 0;
   379→    let j = 0;
   380→    while (j < stats.len()) {
   381→        let diff = stats[j].key_count as i64 - avg as i64;
   382→        sum_sq_diff = sum_sq_diff + (diff * diff) as u64;
   383→        j = j + 1;
   384→    };
   385→
   386→    let variance = sum_sq_diff / stats.len();
   387→    let std_dev = sqrt(variance);
   388→
   389→    // Find hotspots (>2 std dev from mean)
   390→    let k = 0;
   391→    while (k < stats.len()) {
   392→        if (stats[k].key_count > avg + 2 * std_dev) {
   393→            hotspots.push(stats[k].node_id);
   394→        };
   395→        k = k + 1;
   396→    };
   397→
   398→    hotspots
   399→}
