   401→fn sqrt(x: u64) -> u64 {
   402→    // Simple sqrt approximation
   403→    if (x == 0) return 0;
   404→
   405→    let result = x;
   406→    let i = 0;
   407→    while (i < 10) {
   408→        result = (result + x / result) / 2;
   409→        i = i + 1;
   410→    };
   411→
   412→    result
   413→}
