     3→
     4→use crate::value::Value;
     5→
     6→/// 배열의 모든 요소를 변환합니다 (함수형 맵)
     7→pub fn map_transform(arr: &[Value], transformer: impl Fn(&Value) -> Value) -> Vec<Value> {
     8→    arr.iter().map(|v| transformer(v)).collect()
     9→}
    10→
    11→/// 배열에서 조건을 만족하는 요소를 필터링합니다
    12→pub fn filter_items(arr: &[Value], predicate: impl Fn(&Value) -> bool) -> Vec<Value> {
    13→    arr.iter().filter(|v| predicate(v)).cloned().collect()
    14→}
    15→
    16→/// 배열의 모든 요소를 하나의 값으로 축약합니다 (폴드/리듀스)
    17→pub fn fold_left(arr: &[Value], init: Value, reducer: impl Fn(Value, &Value) -> Value) -> Value {
    18→    arr.iter().fold(init, |acc, v| reducer(acc, v))
    19→}
    20→
    21→/// 배열의 모든 요소를 오른쪽에서 왼쪽으로 축약합니다
    22→pub fn fold_right(arr: &[Value], init: Value, reducer: impl Fn(&Value, Value) -> Value) -> Value {
    23→    arr.iter().rev().fold(init, |acc, v| reducer(v, acc))
    24→}
    25→
    26→/// 배열의 합계를 계산합니다 (숫자만)
    27→pub fn sum(arr: &[Value]) -> Option<f64> {
    28→    let mut total = 0.0;
    29→    for val in arr {
